import pandas as pd


def run(inputs: dict[str, "pd.DataFrame"]) -> dict[str, "pd.DataFrame"]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Build watermark lookup: device_id -> (applied_event_ts, reading)
    watermarks = {}
    for _, row in target_snapshot.iterrows():
        watermarks[row["device_id"]] = row["applied_event_ts"]

    # Filter events: for devices with a watermark, event_ts must be STRICTLY
    # greater than watermark. event_ts == watermark is a replay -> skip.
    # For devices with no watermark (new devices), all events are candidates.
    def survives(row):
        dev = row["device_id"]
        if dev in watermarks:
            wm = watermarks[dev]
            return row["event_ts"] > wm
        return True

    if len(cdc_events) > 0:
        mask = cdc_events.apply(survives, axis=1)
        surviving = cdc_events[mask].copy()
    else:
        surviving = cdc_events.copy()

    # Among surviving events per device, pick the one with max (event_ts, event_seq)
    winners = {}
    if len(surviving) > 0:
        surviving_sorted = surviving.sort_values(
            by=["event_ts", "event_seq"], ascending=[True, True]
        )
        for dev, group in surviving_sorted.groupby("device_id"):
            last = group.iloc[-1]
            winners[dev] = (last["reading"], last["event_ts"])

    # Build result: start with target_snapshot devices, carry forward if no winner
    result_rows = []
    seen_devices = set()

    for _, row in target_snapshot.iterrows():
        dev = row["device_id"]
        seen_devices.add(dev)
        if dev in winners:
            reading, applied_ts = winners[dev]
            result_rows.append(
                {"device_id": dev, "reading": reading, "applied_event_ts": applied_ts}
            )
        else:
            result_rows.append(
                {
                    "device_id": dev,
                    "reading": row["reading"],
                    "applied_event_ts": row["applied_event_ts"],
                }
            )

    # Add new devices (in winners but not in target_snapshot)
    for dev, (reading, applied_ts) in winners.items():
        if dev not in seen_devices:
            result_rows.append(
                {"device_id": dev, "reading": reading, "applied_event_ts": applied_ts}
            )

    new_snapshot = pd.DataFrame(
        result_rows, columns=["device_id", "reading", "applied_event_ts"]
    )

    return {"new_snapshot": new_snapshot}
